const exportWatchEvents = `-- name: ExportWatchEvents :many
SELECT id, media_id, event_type, position_ms, duration_ms,
       client_name, client_ip, decision, occurred_at
FROM watch_events
WHERE user_id = $1
  AND ($2::timestamptz IS NULL
       OR (occurred_at, id) < ($2::timestamptz, $3::uuid))
ORDER BY occurred_at DESC, id DESC
LIMIT $4::int
`

type ExportWatchEventsParams struct {
	UserID   uuid.UUID          `json:"user_id"`
	BeforeAt pgtype.Timestamptz `json:"before_at"`
	BeforeID uuid.UUID          `json:"before_id"`
	Lim      int32              `json:"lim"`
}

type ExportWatchEventsRow struct {
	ID         uuid.UUID          `json:"id"`
	MediaID    uuid.UUID          `json:"media_id"`
	EventType  string             `json:"event_type"`
	PositionMs int64              `json:"position_ms"`
	DurationMs *int64             `json:"duration_ms"`
	ClientName *string            `json:"client_name"`
	ClientIp   *netip.Addr        `json:"client_ip"`
	Decision   *string            `json:"decision"`
	OccurredAt pgtype.Timestamptz `json:"occurred_at"`
}

// Play events, newest first, keyset-paged on (occurred_at, id). The handler
// caps the total.
func (q *Queries) ExportWatchEvents(ctx context.Context, arg ExportWatchEventsParams) ([]ExportWatchEventsRow, error) {
	rows, err := q.db.Query(ctx, exportWatchEvents,
		arg.UserID,
		arg.BeforeAt,
		arg.BeforeID,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ExportWatchEventsRow{}
	for rows.Next() {
		var i ExportWatchEventsRow
		if err := rows.Scan(
			&i.ID,
			&i.MediaID,
			&i.EventType,
			&i.PositionMs,
			&i.DurationMs,
			&i.ClientName,
			&i.ClientIp,
			&i.Decision,
			&i.OccurredAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

